      generic: "chronic weight management medication comparison",
      aliases: ["weight loss drug classes", "obesity medication comparison", "phentermine orlistat Contrave Qsymia GLP1", "why stop weight loss medicine if not working"],
      class: "Mechanism, duration, response-checkpoint, and safety comparison for obesity pharmacotherapy",
      entryType: "drug-class-card", classCard: true, isDrugClassCard: true,
      classExampleNames: ["Phentermine", "Orlistat", "Naltrexone/bupropion", "Phentermine/topiramate", "Semaglutide", "Liraglutide", "Tirzepatide"],
