      aliases: ["Qsymia", "phentermine topiramate ER", "phentermine and topiramate", "Qsymia weight loss", "chronic phentermine combination", "phentarmine topirimate", "phentermine topirimate"],
      brandExamples: ["Qsymia"],
      class: "Extended-release norepinephrine-promoting sympathomimetic anorectic plus GABA/glutamate/carbonic-anhydrase-modulating anticonvulsant for chronic weight management",
